const BASE = location.pathname.startsWith('/esign') ? '/esign' : '';
const root = document.querySelector('#app');
const state = { user:null, templates:[], patients:[], episodes:[], documents:[], staff:[], tab:'documents' };
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = (v) => v ? new Date(v).toLocaleString('ru-RU') : '—';
const statusClass = (s='') => /SEALED|DELIVERED|ARCHIVED|ACTIVE/.test(s) ? 'ok' : /FAILED|CANCEL|DECLINED/.test(s) ? 'danger' : 'warn';

async function api(path, options={}) {
  const res = await fetch(`${BASE}${path}`, { credentials:'same-origin', ...options, headers:{'content-type':'application/json', ...(options.headers||{})} });
  const type = res.headers.get('content-type') || '';
  const body = type.includes('json') ? await res.json() : await res.text();
  if (!res.ok) { const e = new Error(body?.error || `HTTP ${res.status}`); e.status=res.status; e.body=body; throw e; }
  return body;
}
function notice(text, kind='notice') { return `<div class="notice ${kind}">${esc(text)}</div>`; }
function field(name,label,type='text',value='',required=false,wide=false){return `<label class="${wide?'wide':''}">${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;}
function textarea(name,label,value='',required=false){return `<label class="wide">${esc(label)}<textarea name="${esc(name)}" ${required?'required':''}>${esc(value)}</textarea></label>`;}
function formData(form){return Object.fromEntries(new FormData(form).entries());}

async function loginView(message='') {
  root.innerHTML=`<div class="login"><form class="card stack" id="login-form"><h1>Expert Dental</h1><p class="muted">Защищённая система электронных документов</p>${message?notice(message,'error'):''}${field('username','Логин','text','',true)}${field('password','Пароль','password','',true)}${field('totp','Код MFA (если включён)')}<button class="btn" type="submit">Войти</button><p class="muted">Түндүк/ОЭП не используется на этапе P0. Все действия журналируются.</p></form></div>`;
  document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();try{const body=formData(e.currentTarget);state.user=await api('/api/auth/login',{method:'POST',body:JSON.stringify(body)});await loadAll();renderDashboard();}catch(err){loginView(err.message);}});
}
async function boot(){
  const signCode=new URLSearchParams(location.search).get('sign');
  if(signCode) return signingView(signCode);
  try{state.user=(await api('/api/auth/me')).user;await loadAll();renderDashboard();}catch{loginView();}
  if('serviceWorker'in navigator) navigator.serviceWorker.register(`${BASE}/service-worker.js`).catch(()=>{});
}
async function loadAll(){
  const [t,p,e,d,s]=await Promise.all([api('/api/templates'),api('/api/patients'),api('/api/episodes'),api('/api/documents'),api('/api/staff')]);
  state.templates=t.templates;state.patients=p.patients;state.episodes=e.episodes;state.documents=d.documents;state.staff=s.staff;
}
function top(){return `<header class="topbar"><div class="shell topbar__row"><div><div class="brand">Expert Dental · Документы</div><small>${esc(state.user.displayName||state.user.display_name||state.user.username)} · ${esc(state.user.role)}</small></div><button class="btn secondary small" id="logout">Выйти</button></div></header>`;}
function tabs(){const list=[['documents','Документы'],['create','Новый документ'],['patients','Пациенты'],['integrations','Интеграции']];if(['compliance','system_admin'].includes(state.user.role))list.push(['staff','Сотрудники']);return `<div class="tabs">${list.map(([id,l])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}">${l}</button>`).join('')}</div>`;}
function renderDashboard(){
  root.innerHTML=`${top()}<main><div class="shell stack">${tabs()}<section id="panel"></section></div></main>`;
  document.querySelector('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});state.user=null;loginView();};
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderDashboard();});
  ({documents:documentsPanel,create:createPanel,patients:patientsPanel,integrations:integrationsPanel,staff:staffPanel}[state.tab]||documentsPanel)();
}
function documentsPanel(){
  const rows=state.documents.map(d=>`<tr><td><strong>${esc(d.document_number)}</strong><br><span class="muted">${esc(d.template_code)} v${esc(d.template_version)}</span></td><td>${esc(d.patient_name)}</td><td>${esc(d.template_title)}</td><td><span class="badge ${statusClass(d.status)}">${esc(d.status)}</span></td><td>${date(d.created_at)}</td><td><div class="row">${['DOCTOR_REVIEW','DRAFT'].includes(d.status)&&['doctor','compliance','system_admin','clinic_authorized'].includes(state.user.role)?`<button class="btn small" data-approve="${d.id}">Утвердить</button>`:''}${d.status==='READY_FOR_PATIENT_SIGNATURE'&&['administrator','compliance','system_admin'].includes(state.user.role)?`<button class="btn small" data-session="${d.id}">Подписать</button>`:''}${d.final_pdf_key?`<a class="btn secondary small" href="${BASE}/api/documents/${d.id}/pdf" target="_blank">PDF</a>`:''}${d.final_pdf_key&&['administrator','compliance','system_admin'].includes(state.user.role)?`<button class="btn secondary small" data-send="${d.id}">WA</button>`:''}${d.final_pdf_key&&['compliance','system_admin'].includes(state.user.role)?`<a class="btn secondary small" href="${BASE}/api/documents/${d.id}/evidence.zip">Evidence</a><button class="btn danger small" data-hold="${d.id}">Legal hold</button>`:''}</div></td></tr>`).join('');
  document.querySelector('#panel').innerHTML=`<div class="card stack"><div class="row between"><div><h1>Документы</h1><p class="muted">Подписанный текст не редактируется. Исправление — новая версия.</p></div><button class="btn secondary" id="refresh">Обновить</button></div><div class="table-wrap"><table><thead><tr><th>DOC-ID</th><th>Пациент</th><th>Форма</th><th>Статус</th><th>Создан</th><th>Действия</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Документов нет</td></tr>'}</tbody></table></div></div>`;
  document.querySelector('#refresh').onclick=async()=>{await loadAll();renderDashboard();};
  document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{if(!confirm('Подтвердить медицинское/организационное содержание и заблокировать текст?'))return;try{await api(`/api/documents/${b.dataset.approve}/approve`,{method:'POST',body:'{}'});await loadAll();renderDashboard();}catch(e){alert(e.message);}});
  document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>sessionDialog(b.dataset.session));
  document.querySelectorAll('[data-send]').forEach(b=>b.onclick=async()=>{const phone=prompt('Телефон пациента в формате +996… (пусто — из карточки)')||undefined;try{await api(`/api/documents/${b.dataset.send}/deliver/whatsapp`,{method:'POST',body:JSON.stringify({phoneE164:phone})});alert('Документ передан WAHA');await loadAll();renderDashboard();}catch(e){alert(e.message);}});
  document.querySelectorAll('[data-hold]').forEach(b=>b.onclick=async()=>{const reason=prompt('Основание legal hold');if(!reason)return;try{await api(`/api/documents/${b.dataset.hold}/legal-hold`,{method:'POST',body:JSON.stringify({reason})});await loadAll();renderDashboard();}catch(e){alert(e.message);}});
}
function patientOptions(){return `<option value="">Выберите пациента</option>${state.patients.map(p=>`<option value="${p.id}">${esc(p.full_name)} · ${esc(p.phone_e164||'без телефона')}</option>`).join('')}`;}
function doctorOptions(){return `<option value="">Выберите врача</option>${state.staff.filter(s=>s.role==='doctor').map(s=>`<option value="${s.id}">${esc(s.display_name)}</option>`).join('')}`;}
function patientsPanel(){
  document.querySelector('#panel').innerHTML=`<div class="grid grid-2"><form class="card stack" id="patient-form"><h2>Новый пациент</h2><div class="field-grid">${field('fullName','ФИО','text','',true,true)}${field('birthDate','Дата рождения','date','',false)}${field('phoneE164','Телефон','tel','+996')}${field('externalCrmId','ID в CRM')}${field('identityMethod','Способ идентификации','text','Документ, удостоверяющий личность')}${field('identityReference','Реквизиты/маскированная ссылка')}</div><button class="btn">Сохранить пациента</button></form><form class="card stack" id="episode-form"><h2>Новый медицинский эпизод</h2><label>Пациент<select name="patientId" required>${patientOptions()}</select></label><label>Направление<select name="direction" required><option>Терапия</option><option>Эндодонтия</option><option>Ортодонтия</option><option>Ортопедия</option><option>Хирургия</option><option>Имплантация</option></select></label><label>Врач<select name="doctorId">${doctorOptions()}</select></label>${field('externalCrmId','ID эпизода в CRM')}<button class="btn">Открыть эпизод</button></form></div>`;
  document.querySelector('#patient-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/patients',{method:'POST',body:JSON.stringify(formData(e.currentTarget))});await loadAll();alert('Пациент сохранён');renderDashboard();}catch(err){alert(err.message);}};
  document.querySelector('#episode-form').onsubmit=async e=>{e.preventDefault();const v=formData(e.currentTarget);if(!v.doctorId)delete v.doctorId;try{await api('/api/episodes',{method:'POST',body:JSON.stringify(v)});await loadAll();alert('Эпизод открыт');renderDashboard();}catch(err){alert(err.message);}};
}
async function createPanel(){
  const usable=state.templates.filter(t=>t.status==='ACTIVE'||true);
  document.querySelector('#panel').innerHTML=`<div class="card stack"><h1>Новый документ</h1>${notice('Формы со статусом COUNSEL_REVIEW_REQUIRED допустимы только в закрытом пилоте. Перед реальным использованием их должен активировать compliance после письменного заключения юриста и медицинского утверждения.')}<form id="doc-form" class="stack"><div class="grid grid-3"><label>Пациент<select id="doc-patient" name="patientId" required>${patientOptions()}</select></label><label>Эпизод<select id="doc-episode" name="episodeId"><option value="">Без эпизода</option>${state.episodes.map(e=>`<option value="${e.id}" data-patient="${e.patient_id}">${esc(e.patient_name)} · ${esc(e.direction)}</option>`).join('')}</select></label><label>Шаблон<select id="doc-template" name="templateVersionId" required><option value="">Выберите форму</option>${usable.map(t=>`<option value="${t.id}">${esc(t.template_code)} · ${esc(t.title)} · ${esc(t.status)}</option>`).join('')}</select></label></div><div id="dynamic-fields" class="field-grid"></div><button class="btn" type="submit">Сформировать документ</button></form></div>`;
  const tplSelect=document.querySelector('#doc-template');
  tplSelect.onchange=async()=>{const id=tplSelect.value;if(!id)return;const t=(await api(`/api/templates/${id}`)).template.body;const box=document.querySelector('#dynamic-fields');box.innerHTML=t.fields.map(f=>{const wide=['textarea','line_items','line_items_money','yes_no_details','multi_select','money_delta'].includes(f.type);return f.type==='boolean'?`<label class="${wide?'wide':''}">${esc(f.label)}<select name="f_${esc(f.key)}" ${f.required?'required':''}><option value="">—</option><option value="true">Да</option><option value="false">Нет</option></select></label>`:wide?textarea(`f_${f.key}`,f.label,'',f.required):field(`f_${f.key}`,f.label,f.type==='date'?'date':'text','',f.required,wide);}).join('');};
  document.querySelector('#doc-form').onsubmit=async e=>{e.preventDefault();const v=formData(e.currentTarget);const fields={};for(const[k,val]of Object.entries(v)){if(k.startsWith('f_'))fields[k.slice(2)]=val;}const body={patientId:v.patientId,templateVersionId:v.templateVersionId,fields};if(v.episodeId)body.episodeId=v.episodeId;try{await api('/api/documents',{method:'POST',body:JSON.stringify(body)});await loadAll();state.tab='documents';renderDashboard();}catch(err){alert(`${err.message}\n${JSON.stringify(err.body?.details||'')}`);}};
}
async function sessionDialog(id){
  const identityMethod=prompt('Способ идентификации','Документ, удостоверяющий личность');if(!identityMethod)return;const identityReference=prompt('Реквизиты проверки (без лишней копии документа)','');const deviceCode=prompt('Код планшета (если зарегистрирован)','IPAD-RECEPTION-01');try{const s=await api(`/api/documents/${id}/signing-session`,{method:'POST',body:JSON.stringify({signerType:'patient',identityMethod,identityReference,deviceCode})});document.querySelector('#panel').innerHTML=`<div class="card stack"><h1>Сессия готова</h1><p>Администратор открывает на iPad:</p><p class="code">${esc(s.code)}</p><p><a href="${esc(s.signingUrl)}" target="_blank">Открыть подписную сессию</a></p><p class="muted">Действует до ${date(s.expiresAt)}. Не передавайте код пациенту для удалённого подписания: P0 предполагает очную сессию под контролем администратора.</p><button class="btn secondary" id="back">Вернуться</button></div>`;document.querySelector('#back').onclick=()=>renderDashboard();}catch(e){alert(e.message);}
}
async function integrationsPanel(){
  const i=await api('/api/integrations/status');document.querySelector('#panel').innerHTML=`<div class="grid grid-3"><div class="card"><h2>WAHA</h2><p class="kpi">${i.waha.ok?'Готов':'Не готов'}</p><pre class="mono">${esc(JSON.stringify(i.waha,null,2))}</pre></div><div class="card"><h2>RFC 3161 TSA</h2><p class="kpi">${i.tsa.enabled?'Включён':'Выключен'}</p><pre class="mono">${esc(JSON.stringify(i.tsa,null,2))}</pre></div><div class="card"><h2>Түндүк/ОЭП</h2><p class="kpi">Следующий этап</p><p class="muted">DEFERRED_INTEGRATION_GATE</p></div></div>`;
}
function staffPanel(){
  document.querySelector('#panel').innerHTML=`<div class="grid grid-2"><form class="card stack" id="staff-form"><h2>Создать сотрудника</h2>${field('username','Логин','text','',true)}${field('displayName','ФИО','text','',true)}<label>Роль<select name="role"><option value="doctor">Врач</option><option value="administrator">Администратор</option><option value="clinic_authorized">Уполномоченное лицо ИП</option><option value="compliance">Compliance</option></select></label>${field('password','Временный пароль (не менее 12 символов)','password','',true)}<button class="btn">Создать</button></form><div class="card"><h2>Сотрудники</h2>${state.staff.map(s=>`<p><strong>${esc(s.display_name)}</strong><br><span class="muted">${esc(s.username)} · ${esc(s.role)}</span></p>`).join('')}</div></div>`;
  document.querySelector('#staff-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/staff',{method:'POST',body:JSON.stringify(formData(e.currentTarget))});await loadAll();renderDashboard();}catch(err){alert(err.message);}};
}

async function signingView(code){
  root.innerHTML=`<div class="fullscreen-message"><div><h1>Загрузка документа…</h1><p class="muted">Не закрывайте экран.</p></div></div>`;
  try{const data=await api(`/api/sign/${encodeURIComponent(code)}`);renderSigning(data,code);}catch(e){root.innerHTML=`<div class="fullscreen-message"><div>${notice(e.message,'error')}<h1>Сессия недоступна</h1><p>Обратитесь к администратору.</p></div></div>`;}
}
function renderSigning(data,code){
  const s=data.snapshot;const sections=s.sections.map(x=>`<section><h2>${esc(x.heading)}</h2>${x.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('');const fields=s.fields?.length?`<section><h2>Зафиксированные данные</h2>${s.fields.map(f=>`<p><strong>${esc(f.label)}:</strong> ${esc(f.displayValue)}</p>`).join('')}</section>`:'';
  root.innerHTML=`<div class="sign-shell"><div class="sign-top"><strong>${esc(data.documentNumber)}</strong> · ${esc(s.template.code)} v${esc(s.template.version)}<br><small>Подписант: ${esc(data.signerName)}</small></div><div class="sign-doc"><div class="sign-content" id="doc-scroll"><h1>${esc(s.template.title)}</h1><p class="meta">Исполнитель: ${esc(s.clinic.legalName)} · ${esc(s.clinic.license)}<br>Пациент: ${esc(data.patientName)}${s.doctor?` · Врач: ${esc(s.doctor.displayName)}`:''}</p>${sections}${fields}<div id="doc-end"></div></div><form class="sign-actions stack" id="sign-form"><div id="scroll-note" class="notice">Прокрутите документ до конца. Подпись станет доступна после ознакомления.</div><div id="acks">${s.acknowledgements.map((a,i)=>`<label class="ack"><input type="checkbox" data-ack="${i}" disabled><span>${esc(a)}</span></label>`).join('')}</div><div><h2>Подпись электронным пером</h2><div class="canvas-wrap"><canvas class="signature-canvas" id="signature"></canvas></div><div class="canvas-tools"><span class="muted">Подпись относится только к этому документу.</span><button type="button" class="btn secondary small" id="clear-sign">Очистить</button></div></div><label class="ack"><input id="wa-copy" type="checkbox" checked><span>Направить мне подписанную копию через WhatsApp на номер из карточки пациента.</span></label><button class="btn sign-final" id="sign-submit" disabled>Подписать документ</button></form></div></div>`;
  const scroll=document.querySelector('#doc-scroll'),checks=[...document.querySelectorAll('[data-ack]')],submit=document.querySelector('#sign-submit'),canvas=document.querySelector('#signature'),ctx=canvas.getContext('2d');let scrollDone=false,strokes=[],drawing=false;
  const resize=()=>{const r=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;const old=canvas.toDataURL();canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#102a25';if(strokes.length)redraw();};
  const redraw=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);if(!strokes.length)return;ctx.beginPath();strokes.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();};resize();addEventListener('resize',resize);
  const ready=()=>{submit.disabled=!(scrollDone&&checks.every(c=>c.checked)&&strokes.length>4);};checks.forEach(c=>c.onchange=ready);
  const reached=()=>{if(scroll.scrollTop+scroll.clientHeight>=scroll.scrollHeight-12){scrollDone=true;checks.forEach(c=>c.disabled=false);document.querySelector('#scroll-note').className='notice success';document.querySelector('#scroll-note').textContent='Документ показан полностью. Подтвердите пункты и поставьте подпись.';api(`/api/sign/${encodeURIComponent(code)}/presented`,{method:'POST',body:'{}'}).catch(()=>{});ready();}};scroll.addEventListener('scroll',reached);setTimeout(reached,300);
  const point=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top,t:performance.now()}};
  canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);const p=point(e);strokes.push(p);ctx.beginPath();ctx.moveTo(p.x,p.y);};canvas.onpointermove=e=>{if(!drawing)return;const p=point(e);strokes.push(p);ctx.lineTo(p.x,p.y);ctx.stroke();ready();};canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;ready();};document.querySelector('#clear-sign').onclick=()=>{strokes=[];ctx.clearRect(0,0,canvas.width,canvas.height);ready();};
  document.querySelector('#sign-form').onsubmit=async e=>{e.preventDefault();if(submit.disabled)return;if(!confirm(`Вы подписываете ${data.documentNumber}. После подписания текст изменить нельзя. Продолжить?`))return;submit.disabled=true;submit.textContent='Запечатываем документ…';const ack={};checks.forEach(c=>ack[c.dataset.ack]=c.checked);try{const result=await api(`/api/sign/${encodeURIComponent(code)}`,{method:'POST',body:JSON.stringify({scrollCompleted:true,acknowledgements:ack,signature:{pngDataUrl:canvas.toDataURL('image/png'),strokes},delivery:{whatsapp:document.querySelector('#wa-copy').checked}})});root.innerHTML=`<div class="fullscreen-message"><div><h1>Документ подписан</h1><p class="code">${esc(result.documentNumber)}</p>${notice(result.delivery?.status==='SENT'?'Копия направлена через WhatsApp.':'Документ сохранён. Администратор проверит выдачу копии.','success')}<p class="mono">SHA-256: ${esc(result.finalPdfHash)}</p><p class="muted">Передайте планшет администратору.</p></div></div>`;}catch(err){submit.disabled=false;submit.textContent='Подписать документ';alert(err.message);}};
}

boot();
